# Generated by OrchestKit Claude Plugin
# Created: 2026-07-31

"""Reading a `stream-json` run back (T2.4). No Docker, no model — a recorded run.

The fixture is a real run, redacted: two probes on 2026-07-31 established these shapes against
`claude 2.1.220`, and two of them contradict the design note this suite was written from.

* the `init` event carries **lists** — `skills`, `plugins`, `slash_commands` — not the
  `n_skills` / `n_plugins` counters the note reported. A self-check written from the note would
  have read `event.get("n_skills", 0) == 0` and passed on a *fully contaminated* run;
* at `init` the gramps server's status is **`pending`**, and `tools` is **`["ToolSearch"]`**.
  MCP tools are deferred, so "the server connected" is not visible in the init event at all.
  What is visible is behaviour: a `tool_reference` block naming `mcp__gramps__…`, or a call to
  one. That is what the self-check gates on.

A `tool_result` may carry either a string or a list of blocks — both were observed in the same
run — so the parser handles both rather than the one it happened to see first.
"""

from __future__ import annotations

import json
from pathlib import Path

import pytest
from harness.docker_util import ProbeError
from stage2 import transcript

FIXTURE = Path(__file__).parent / "fixtures" / "stage2" / "clean-run.jsonl"


@pytest.fixture(scope="module")
def run() -> transcript.Transcript:
    return transcript.load(FIXTURE)


def test_the_init_event_is_found_past_the_noise(run: transcript.Transcript) -> None:
    """A `rate_limit_event` sits between init and the first turn; it is not a message."""
    assert run.init["claude_code_version"] == "2.1.220"


def test_every_tool_use_is_recorded_in_order(run: transcript.Transcript) -> None:
    assert [use.name for use in run.tool_uses] == [
        "ToolSearch",
        "mcp__gramps__gramps_add_person",
    ]


def test_the_gramps_calls_are_the_wire_log_the_grader_reads(run: transcript.Transcript) -> None:
    """Decision (d): every call with its arguments. The prefix is dropped — the catalog names
    tools as `server.py` registers them."""
    (call,) = run.gramps_calls

    assert call.name == "gramps_add_person"
    assert call.arguments["first_name"] == "Wendelmark"


def test_what_tool_search_surfaced_is_kept(run: transcript.Transcript) -> None:
    """Half of the docstring contract is *findability*: a tool the search never returns was
    never offered to the model, which is a different defect from one it saw and misused."""
    assert run.references == {
        "mcp__gramps__gramps_add_person",
        "mcp__gramps__gramps_list_people",
    }


def test_a_string_tool_result_is_read(run: transcript.Transcript) -> None:
    assert "I0042" in run.tool_results[-1].text
    assert run.tool_results[-1].is_error is False


def test_the_result_event_is_the_run_accounting(run: transcript.Transcript) -> None:
    assert run.num_turns == 4
    assert run.cost_usd == pytest.approx(0.0791895)
    assert run.subtype == "success"
    assert run.is_error is False
    assert run.permission_denials == []


def test_the_final_text_is_available_for_the_canary(run: transcript.Transcript) -> None:
    assert run.text.startswith("Added Wendelmark")


def test_a_half_written_line_is_refused(tmp_path: Path) -> None:
    """A truncated JSONL must not read as "the model called nothing" — that is a false red."""
    lines = FIXTURE.read_text(encoding="utf-8").splitlines()
    broken = tmp_path / "run.jsonl"
    broken.write_text("\n".join(lines[:-1] + ['{"type":"resu']), encoding="utf-8")

    with pytest.raises(ProbeError, match="line 8"):
        transcript.load(broken)


def test_a_run_without_a_result_event_is_refused(tmp_path: Path) -> None:
    """`timeout` kills the process mid-stream; the log then ends without accounting."""
    lines = FIXTURE.read_text(encoding="utf-8").splitlines()[:-1]
    partial = tmp_path / "run.jsonl"
    partial.write_text("\n".join(lines) + "\n", encoding="utf-8")

    with pytest.raises(ProbeError, match="result"):
        transcript.load(partial)


def test_a_run_without_an_init_event_is_refused(tmp_path: Path) -> None:
    """No init means nothing about the run's isolation can be checked at all."""
    lines = FIXTURE.read_text(encoding="utf-8").splitlines()[1:]
    headless = tmp_path / "run.jsonl"
    headless.write_text("\n".join(lines) + "\n", encoding="utf-8")

    with pytest.raises(ProbeError, match="init"):
        transcript.load(headless)


def test_an_empty_log_is_refused(tmp_path: Path) -> None:
    empty = tmp_path / "run.jsonl"
    empty.write_text("", encoding="utf-8")

    with pytest.raises(ProbeError, match="empty"):
        transcript.load(empty)


def test_an_error_tool_result_is_marked_as_one(tmp_path: Path) -> None:
    """The observed shape: `content` a string, `is_error` true, alongside the same `tool_use_id`."""
    events = transcript.read_events(FIXTURE)
    events[5]["message"]["content"][0] |= {
        "content": "Error executing tool gramps_add_person: boom",
        "is_error": True,
    }

    parsed = transcript.from_events(events)

    assert parsed.tool_results[-1].is_error is True
    assert "boom" in parsed.tool_results[-1].text


def test_reading_events_leaves_the_file_alone() -> None:
    """The parser is the only reader of a run directory; it must not rewrite the evidence."""
    before = FIXTURE.read_bytes()
    transcript.load(FIXTURE)

    assert FIXTURE.read_bytes() == before
    assert json.loads(before.splitlines()[0])["type"] == "system"
